#nullable enable
using System.Collections.Immutable;
using HourBooking.Contracts;

namespace HourBooking.Slices.Booking;

/// <summary>
/// Live aggregation over the Timesheet stream, keyed by employeeId + month. Nothing registers a
/// projection for this: Marten folds it on demand when the endpoint asks.
///
/// Folds every event of the stream, not only this slice's, because the decision depends on all of
/// them — the daily cap needs the whole month's bookings, not just the one being added.
///
/// The model draws HoursBooked first in this stream, but there is deliberately no Create method: a
/// no-arg constructor lets any event open the stream. ZeroHoursFilled can be first, when an employee
/// leaves a project having booked nothing that month. See ANTI-PATTERNS.md #1.
/// </summary>
public sealed record BookHoursState
{
    /// <summary>From the domain expert: "at most 18 hours can stand for one day".</summary>
    public const decimal DailyCap = 18m;

    public string Id { get; init; } = default!;

    /// <summary>Marten's convention. The aggregate workflow uses it for optimistic concurrency.</summary>
    public int Version { get; set; }

    /// <summary>
    /// One line per booking still standing, keyed by bookingId because that is all HoursCorrected
    /// and BookingRemoved carry. Which is exactly why the stream is per (employee, month) and not
    /// per booking: a correction's date and project are already known here from when it was booked.
    /// </summary>
    public ImmutableDictionary<Guid, Line> Lines { get; init; } = ImmutableDictionary<Guid, Line>.Empty;

    public sealed record Line(DateOnly Date, Guid ProjectId, decimal Hours);

    public static string StreamKey(Guid employeeId, string month) => $"timesheet:{employeeId}:{month}";

    // --- what the endpoint asks it ---------------------------------------------------------------

    public decimal HoursOn(DateOnly date) => Lines.Values.Where(l => l.Date == date).Sum(l => l.Hours);

    /// <summary>
    /// "There may be only one HoursBooked per day+project. Booking again is a Correction." That is
    /// what makes BookHours non-idempotent, and it is a modelling fact rather than UI polish.
    /// </summary>
    public bool AlreadyBooked(DateOnly date, Guid projectId) =>
        Lines.Values.Any(l => l.Date == date && l.ProjectId == projectId);

    // --- the fold --------------------------------------------------------------------------------

    public static BookHoursState Apply(HoursBooked e, BookHoursState current) =>
        current with { Lines = current.Lines.SetItem(e.BookingId, new Line(e.Date, e.ProjectId, e.Hours)) };

    /// <summary>
    /// A correction carries the new TOTAL, not a delta — the expert was explicit: "a HoursCorrected
    /// event carrying the 8 hours, not the 2 difference". It has no date or project of its own, so
    /// the standing line supplies both.
    /// </summary>
    public static BookHoursState Apply(HoursCorrected e, BookHoursState current) =>
        current.Lines.TryGetValue(e.BookingId, out var line)
            ? current with { Lines = current.Lines.SetItem(e.BookingId, line with { Hours = e.Hours }) }
            : current;

    public static BookHoursState Apply(BookingRemoved e, BookHoursState current) =>
        current with { Lines = current.Lines.Remove(e.BookingId) };

    /// <summary>A zero-filled day is still a booked day+project, so it blocks a second booking.</summary>
    public static BookHoursState Apply(ZeroHoursFilled e, BookHoursState current) =>
        current with { Lines = current.Lines.SetItem(e.BookingId, new Line(e.Date, e.ProjectId, e.Hours)) };
}
